// TestWordObjectFailureRepeat checks that a word object that fails isn't
// the change . repeats: after x, d5aw on three words fails and . repeats the
// x.
func TestWordObjectFailureRepeat(t *testing.T) {
	runWordObjectCases(t, []wordObjectCase{
		{name: "x first: xd5aw.", content: "Xabc def\nghi", keys: "xd5aw.", text: "abc def\ngh", want: Position{1, 1}, col: 1, reg: anyReg},
		{name: "x first: xd9iw.", content: "Xabc def\nghi", keys: "xd9iw.", text: "abc def\ngh", want: Position{1, 1}, col: 1, reg: anyReg},
		{name: "x first: x$daw.", content: "Xabc def\nghi", keys: "x$daw.", text: "\nghi", want: Position{0, 0}, col: 0, reg: anyReg},
		{name: "x first: xjd3aw.", content: "Xabc def\nghi", keys: "xjd3aw.", text: "abc def\ngh", want: Position{1, 1}, col: 1, reg: anyReg},
		{name: "x first: x2d3aw.", content: "Xabc def\nghi", keys: "x2d3aw.", text: "abc def\ngh", want: Position{1, 1}, col: 1, reg: anyReg},
		{name: "x first: xv5awd.", content: "Xabc def\nghi", keys: "xv5awd.", text: "", want: Position{0, 0}, col: 0, reg: anyReg},
		{name: "x empty last: xjdaw.", content: "Xabc\n\n", keys: "xjdaw.", text: "abc\n", want: Position{1, 0}, col: 0, reg: anyReg},
		{name: "x one empty: xdaw.", content: "X", keys: "xdaw.", text: "", want: Position{0, 0}, col: 0, reg: anyReg},
		{name: "x one empty: xdiw.", content: "X", keys: "xdiw.", text: "", want: Position{0, 0}, col: 0, reg: anyReg},
		{name: "x one empty: xd2iw.", content: "X", keys: "xd2iw.", text: "", want: Position{0, 0}, col: 0, reg: anyReg},
	})
}

